1	import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
2	import { EdgeTracer, EdgeMetrics } from "../requisicao-automatica-ia/telemetry.ts";
3	
4	// Agente revisor (segunda opinião) dos matches da requisição MANUAL.
5	// Olha cada item já matcheado e, se PELO NOME outro produto do catálogo combina
6	// claramente melhor, sinaliza — não muda nada, só avisa o operador (Sim/Não na UI).
7	// Best-effort: qualquer falha retorna flags=[] sem quebrar o fluxo do frontend.
8	
9	const corsHeaders = {
10	  'Access-Control-Allow-Origin': '*',
11	  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-application, traceparent',
12	};
13	
14	// Mesmo chain barato do parser manual. Primário = gpt-4.1-mini: comprovadamente confiável
15	// p/ JSON estrito desta tarefa (grok-4.1-fast falhava e caía pro fallback, desperdiçando uma
16	// ida à API + latência). grok fica como fallback baratíssimo. Dispara o próximo em erro/vazio.
17	const FALLBACK_MODELS = [
18	  'deepseek/deepseek-v4-flash',
19	  'openai/gpt-4.1-mini',
20	  'x-ai/grok-4.1-fast',
21	  'google/gemini-2.5-flash',
22	  'qwen/qwen3-32b',
23	];
24	
25	const SYSTEM_PROMPT = `Você é um REVISOR de matches de produtos da MOMMA (doces artesanais).
26	
27	Recebe uma lista de [ITENS]. Cada item tem:
28	- "texto": o que o operador digitou (verbatim)
29	- "match": o produto ao qual o sistema associou esse texto
30	
31	E recebe o [CATÁLOGO] de produtos válidos (produtos_master).
32	
33	TAREFA: para cada item, decidir se o "match" está correto OU se, PELO NOME, outro
34	produto do catálogo combina CLARAMENTE melhor com o "texto".
35	
36	REGRAS:
37	- Seja CONSERVADOR. Só sinalize quando houver divergência CLARA. Ex.: texto "morango"
38	  matcheado como "Café em Grão", existindo "Bombom Morango" no catálogo.
39	- Se o match estiver plausível, NÃO sinalize.
40	- Variação ortográfica/abreviação normal do português NÃO é erro: "banoffe"="Banoffee",
41	  "cx"=caixa, "doce de leite"="Doce de Leite", plural/singular, acento. Ignore isso.
42	- "suggested_name" DEVE ser um nome EXATO existente no [CATÁLOGO]. Nunca invente.
43	- Considere o sabor/variante como sinal principal de correspondência.
44	
45	SAÍDA — JSON estrito, contendo SOMENTE os itens suspeitos (use o índice numérico do item):
46	{
47	  "flags": [
48	    { "index": 2, "suggested_name": "Bombom Morango", "reason": "texto 'morango' combina com Bombom Morango; match atual é de outra categoria" }
49	  ]
50	}
51	Se nenhum item for suspeito, retorne exatamente: { "flags": [] }
52	Não escreva nada fora do JSON.`;
53	
54	interface LlmResult {
55	  content: string;
56	  usage: { prompt_tokens?: number; completion_tokens?: number } | null;
57	}
58	
59	async function callModel(prompt: string, model: string): Promise<LlmResult> {
60	  const apiKey = Deno.env.get('OPENROUTER_API_KEY');
61	  if (!apiKey) throw new Error('OPENROUTER_API_KEY not set');
62	  const res = await fetch('https://openrouter.ai/api/v1/chat/completions', {
63	    method: 'POST',
64	    headers: {
65	      'Authorization': `Bearer ${apiKey}`,
66	      'Content-Type': 'application/json',
67	      'HTTP-Referer': 'https://momma-stock-insight.vercel.app',
68	      'X-Title': 'momma-match-review',
69	    },
70	    body: JSON.stringify({
71	      model,
72	      messages: [
73	        { role: 'system', content: SYSTEM_PROMPT },
74	        { role: 'user', content: prompt },
75	      ],
76	      temperature: 0,
77	      // Força JSON limpo (sem fences/preâmbulo) — melhora confiabilidade do modelo
78	      // primário (grok) e dos demais; o parse de fallback ainda cobre quem ignorar.
79	      response_format: { type: 'json_object' },
80	    }),
81	  });
82	  if (!res.ok) {
83	    const txt = await res.text().catch(() => '');
84	    throw new Error(`OpenRouter ${model}: ${res.status} ${txt}`);
85	  }
86	  const data = await res.json();
87	  return { content: data?.choices?.[0]?.message?.content ?? '', usage: data?.usage ?? null };
88	}
89	
90	async function callWithFallback(prompt: string): Promise<{ content: string; model: string; usage: LlmResult['usage'] }> {
91	  let lastErr: unknown;
92	  for (const model of FALLBACK_MODELS) {
93	    try {
94	      const { content, usage } = await callModel(prompt, model);
95	      if (content && content.trim()) return { content, model, usage };
96	    } catch (err) {
97	      lastErr = err;
98	      console.warn('[review] model fail', model, err instanceof Error ? err.message : String(err));
99	    }
100	  }
101	  throw lastErr || new Error('Todos os modelos de fallback falharam');
102	}
103	
104	function parseJson(content: string): unknown {
105	  let clean = content.trim();
106	  if (clean.startsWith('```')) {
107	    clean = clean.replace(/^```(?:json)?\s*/, '').replace(/\s*```$/, '');
108	  }
109	  return JSON.parse(clean);
110	}
111	
112	serve(async (req) => {
113	  if (req.method === 'OPTIONS') {
114	    return new Response(null, { headers: corsHeaders });
115	  }
116	
117	  const tracer = new EdgeTracer(req, { serviceName: 'gidape-edge-match-review' });
118	  const metrics = new EdgeMetrics({ serviceName: 'gidape-edge-match-review' });
119	  const rootSpan = tracer.startSpan('review-requisition-matches');
120	
121	  try {
122	    const { items, productCatalog } = await req.json();
123	    if (!Array.isArray(items) || items.length === 0) {
124	      rootSpan.end();
125	      Promise.all([tracer.flush(), metrics.flush()]).catch(() => {});
126	      return new Response(JSON.stringify({ flags: [] }), {
127	        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
128	      });
129	    }
130	    rootSpan.setAttribute('review.items', items.length);
131	
132	    const catalogLines = (Array.isArray(productCatalog) ? productCatalog : [])
133	      .slice(0, 300) // cap p/ evitar overflow de token
134	      .map((p: { name?: string }) => String(p?.name ?? '').trim())
135	      .filter(Boolean)
136	      .join('\n');
137	
138	    const itemLines = items
139	      .map(
140	        (it: { texto?: string; match?: string }, i: number) =>
141	          `${i}. texto="${String(it?.texto ?? '').replace(/"/g, "'")}" | match="${String(it?.match ?? '').replace(/"/g, "'")}"`,
142	      )
143	      .join('\n');
144	
145	    const prompt = `[ITENS]\n${itemLines}\n\n[CATÁLOGO]\n${catalogLines}`;
146	
147	    const llmSpan = tracer.startSpan('llm-call-openrouter', rootSpan.spanId);
148	    const llmStart = Date.now();
149	    const { content, model, usage } = await callWithFallback(prompt);
150	    const llmDurationMs = Date.now() - llmStart;
151	    llmSpan.setAttribute('llm.model', model);
152	    llmSpan.setAttribute('llm.provider', 'openrouter');
153	    if (usage) {
154	      const inputTokens = usage.prompt_tokens ?? 0;
155	      const outputTokens = usage.completion_tokens ?? 0;
156	      llmSpan.setAttribute('llm.usage.input_tokens', inputTokens);
157	      llmSpan.setAttribute('llm.usage.output_tokens', outputTokens);
158	      metrics.recordLlmCall({
159	        model,
160	        provider: 'openrouter',
161	        operation: 'match-review',
162	        inputTokens,
163	        outputTokens,
164	        durationMs: llmDurationMs,
165	      });
166	    }
167	    llmSpan.end();
168	
169	    let parsed: { flags?: unknown };
170	    try {
171	      parsed = parseJson(content) as { flags?: unknown };
172	    } catch {
173	      console.warn('[review] parse fail', content?.slice?.(0, 300));
174	      parsed = { flags: [] };
175	    }
176	    const flags = Array.isArray(parsed?.flags) ? parsed.flags : [];
177	    rootSpan.setAttribute('review.flags', flags.length);
178	    rootSpan.end();
179	    Promise.all([tracer.flush(), metrics.flush()]).catch(() => {});
180	
181	    return new Response(JSON.stringify({ flags, model }), {
182	      headers: { ...corsHeaders, 'Content-Type': 'application/json', 'traceparent': tracer.getResponseTraceparent() },
183	    });
184	  } catch (error) {
185	    console.error('[review] fatal', error);
186	    rootSpan.endWithError(error instanceof Error ? error.message : String(error));
187	    Promise.all([tracer.flush(), metrics.flush()]).catch(() => {});
188	    // Best-effort: nunca quebra o fluxo do frontend (review é opcional).
189	    return new Response(
190	      JSON.stringify({ flags: [], error: error instanceof Error ? error.message : String(error) }),
191	      { status: 200, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
192	    );
193	  }
194	});
