1	import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
2	import "https://deno.land/x/xhr@0.1.0/mod.ts";
3	import { EdgeTracer, EdgeMetrics } from "../requisicao-automatica-ia/telemetry.ts";
4	const corsHeaders = {
5	  'Access-Control-Allow-Origin': '*',
6	  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-application, traceparent'
7	};
8	// Cadeia de fallback p/ o match da requisição manual. Tarefa = extração estruturada
9	// simples → priorizamos modelos baratos+rápidos+bons em seguir instrução/JSON.
10	// Variantes PAGAS (não :free) por confiabilidade — uma requisição custa frações de centavo.
11	// Dispara o próximo em erro/JSON inválido/resposta vazia.
12	const FALLBACK_MODELS = [
13	  'deepseek/deepseek-v4-flash', // primário: muito barato ($0.10/$0.20), ctx 1M
14	  'openai/gpt-4.1-mini',        // fallback confiável p/ JSON estrito
15	  'x-ai/grok-4.1-fast',         // fallback baratíssimo
16	  'google/gemini-2.5-flash',    // rápido, forte em extração
17	  'qwen/qwen3-32b'              // mais barato, suporta structured output
18	];
19	
20	function isGrokModel(model: string): boolean {
21	  return /(^|\/)grok/i.test(model);
22	}
23	
24	function logEvent(level: 'info' | 'warning' | 'error', event: string, data: Record<string, unknown> = {}) {
25	  const payload = { ts: new Date().toISOString(), function: 'process-requisition-ai', event, ...data };
26	  if (level === 'error') console.error('[AI]', JSON.stringify(payload));
27	  else if (level === 'warning') console.warn('[AI]', JSON.stringify(payload));
28	  else console.log('[AI]', JSON.stringify(payload));
29	}
30	const SYSTEM_PROMPT = `# MOMMA REQUISITION PARSER — MOTOR DE EXTRAÇÃO DE PRODUTOS
31	
32	Você é um sistema de extração de elite para a **MOMMA**, marca artesanal brasileira de bolos, gelatos, docinhos e outros produtos confeitados.
33	
34	Sua saída aciona pedidos reais de estoque. **Erro = produto errado entregue.**
35	
36	---
37	
38	## ⚡ REGRA #1 — HERANÇA DE CONTEXTO DE CATEGORIA (MAIS CRÍTICA)
39	
40	As mensagens usam formato hierárquico: um **cabeçalho de categoria** seguido de **sub-itens** (apenas sabor/variante).
41	
42	O campo \`name\` DEVE ser o nome COMPLETO do produto = prefixo canônico da categoria + sabor/variante.
43	**NUNCA** escreva apenas o sabor quando houver um cabeçalho de categoria acima.
44	
45	### Mapeamento de Categorias → Prefixos Canônicos
46	
47	| Variantes do cabeçalho (case-insensitive) | Prefixo canônico | Exemplo de nome completo |
48	|---|---|---|
49	| Bolos no pote / Bolo no pote / bolo pote | "Bolo no Pote" | "Bolo no Pote Banoffee" |
50	| Bombons / Bombom | "Bombom" | "Bombom Morango" |
51	| Brownie lowcarb / Brownie low carb / brownie low | "Brownie Low Carb" | "Brownie Low Carb" |
52	| Doces no Pote / Doce no pote / docinhos no pote | "Doce no Pote" | "Doce no Pote Doce de Leite" |
53	| Docinho / Docinhos / docinho bolinha | "Docinho" | "Docinho Misto" |
54	| Mini / Minis | "Mini" | "Mini Ferrero Rocher" |
55	| Tartelete / Tarteletes | "Tartelete" | "Tartelete Chocomelo" |
56	| Fatias / Fatia | "Fatia" | "Fatia Chocomelo" |
57	| Gelatos / Gelato | "Gelato" | "Gelato Frutas Vermelhas" |
58	| Granolas / Granola | "Granola" | "Granola Baunilha" |
59	| Café | "Café" | "Café em Grão" |
60	| Gingerbread | standalone — sem prefixo | "Gingerbread" |
61	| Pronta entrega | standalone — sem prefixo | "Vulcão de Pistache" |
62	
63	**Regra de escopo:** o cabeçalho permanece ativo até o próximo cabeçalho ou até o fim do texto.
64	
65	---
66	
67	## REGRA #2 — SE CATÁLOGO FORNECIDO, USE OS NOMES EXATOS
68	
69	Se houver uma seção \`[CATÁLOGO DE PRODUTOS]\` no input, cada item extraído DEVE ser mapeado ao nome mais próximo do catálogo. O catálogo é a fonte verdade. Prefira o nome exato do catálogo ao invés do nome reconstituído.
70	
71	Estratégia:
72	1. Identificar sabor/variante do texto + prefixo da categoria
73	2. Buscar no catálogo o produto que melhor corresponde
74	3. Usar exatamente esse nome no campo \`name\`
75	
76	---
77	
78	## REGRA #3 — ZERO ALUCINAÇÃO
79	
80	- Não invente produtos que não estão no texto
81	- Não estime quantidades — sem número = 1
82	- Não adicione itens "que geralmente vêm junto"
83	- Se ambíguo, registre na \`observation\`
84	
85	---
86	
87	## REGRA #4 — PARSING DE QUANTIDADES
88	
89	| Formato | Resultado |
90	|---|---|
91	| "3 caixas" / "3cx" / "3 - cx" / "3- cx" | requested=3, observation="caixas" |
92	| "9 UND" / "9 unidades" | requested=9, observation="UND" |
93	| "1 saco" | requested=1, observation="saco" |
94	| "2 - cx" (traço antes de cx) | requested=2, observation="caixas" |
95	| "1k" / "1 kg" | requested=1, observation="1kg" |
96	| apenas número | requested=número |
97	| sem número | requested=1 |
98	
99	---
100	
101	## REGRA #5 — LIMPEZA DE RUÍDO
102	
103	Remova do texto antes de processar:
104	- Timestamps: \`[10:01, 13/03/2026] Breno:\`
105	- Cabeçalhos de requisição: "Requisição 13/03:", "Requisição do dia X"
106	- Emojis, marcadores (*, -, •, números com ponto)
107	- Saudações: "bom dia", "segue lista", "olá"
108	
109	---
110	
111	## ⚡ REGRA #6 — SOURCE_TEXT (RASTREABILIDADE — OBRIGATÓRIO)
112	
113	Cada item DEVE conter o campo \`source_text\`: o trecho **verbatim** do input do usuário que originou aquele item — exatamente como foi digitado, **antes** de você reconstruir o nome canônico.
114	
115	- É a evidência que o humano usa para conferir se o match veio certo. Copie literal do input: NÃO normalize, NÃO corrija ortografia, NÃO traduza, NÃO adicione o prefixo de categoria.
116	- Inclua o sabor/variante e o token de quantidade como apareceram (ex.: "banoffe: 3 caixas").
117	- Ex.: input "banoffe: 3 caixas" sob cabeçalho "Bolos no pote" → \`name\`="Bolo no Pote Banoffee", \`source_text\`="banoffe: 3 caixas".
118	- OBRIGATÓRIO em TODOS os itens (mesmo que os Exemplos 2 e 3 abaixo, por brevidade, nem sempre o repitam).
119	
120	---
121	
122	## FORMATO DE SAÍDA (JSON V2 ESTRITO)
123	
124	\`\`\`json
125	{
126	  "schema_version": "2",
127	  "categories": [
128	    {
129	      "category": "nome_da_categoria",
130	      "items": [
131	        { "name": "Nome Completo Produto", "source_text": "trecho verbatim do input que gerou este item", "requested": 1, "sent": null, "observation": "opcional" }
132	      ]
133	    }
134	  ],
135	  "meta": { "total_items": N, "total_requested": N },
136	  "_debug_verification": "Categorias: X. Itens: Y. Prefixos aplicados: Z. Catálogo usado: sim/não."
137	}
138	\`\`\`
139	
140	---
141	
142	## EXEMPLOS
143	
144	### Exemplo 1 — Mensagem WhatsApp com múltiplas categorias
145	
146	**INPUT:**
147	\`\`\`
148	[10:01, 13/03/2026] Breno: Requisição 13/03:
149	
150	Bolos no pote
151	banoffe: 3 caixas
