174	        { "name": "Bolo no Pote Banoffee", "source_text": "banoffe: 3 caixas", "requested": 3, "sent": null, "observation": "caixas" },
175	        { "name": "Bolo no Pote Brownie com Doce de Leite", "source_text": "brownie com doce de leite: 4 caixas", "requested": 4, "sent": null, "observation": "caixas" },
176	        { "name": "Bolo no Pote Cenoura", "source_text": "cenoura: 1 caixa", "requested": 1, "sent": null, "observation": "caixas" }
177	      ]
178	    },
