181	      "items": [
182	        { "name": "Bombom Morango", "source_text": "morango: 2 caixas", "requested": 2, "sent": null, "observation": "caixas" },
183	        { "name": "Bombom Uva", "source_text": "uva: 2 caixas", "requested": 2, "sent": null, "observation": "caixas" }
184	      ]
185	    },
186	    {
