276	/**
277	 * Agrupa itens por categoria, preservando a ordem de aparição.
278	 * Categorias customizadas vazias são incluídas ao final.
279	 */
280	export function groupItemsByCategory(
281	  items: AIProcessedItem[],
282	  customCategories: string[] = []
283	): Map<string, AIProcessedItem[]> {
284	  const orderedCategories: string[] = [];
285	  const seen = new Set<string>();
286	
287	  // Categorias ordenadas pela primeira aparição nos itens
288	  items.forEach(it => {
289	    const cat = (it.category?.trim() || 'Geral');
290	    if (!seen.has(cat)) {
291	      seen.add(cat);
292	      orderedCategories.push(cat);
293	    }
294	  });
295	
296	  // Categorias customizadas ainda sem itens
297	  customCategories.forEach(cat => {
298	    const name = (cat || '').trim();
299	    if (name && !seen.has(name)) {
300	      seen.add(name);
301	      orderedCategories.push(name);
302	    }
303	  });
304	
305	  // Mapear itens por categoria
306	  const itemsByCategory = new Map<string, AIProcessedItem[]>();
307	  orderedCategories.forEach(cat => itemsByCategory.set(cat, []));
308	  items.forEach(it => {
309	    const cat = (it.category?.trim() || 'Geral');
310	    const arr = itemsByCategory.get(cat) || [];
311	    arr.push(it);
312	    itemsByCategory.set(cat, arr);
313	  });
314	
315	  return itemsByCategory;
316	}
