335	/** Renomeia uma categoria em todos os itens. */
336	export function renameCategoryInItems(
337	  items: AIProcessedItem[],
338	  oldName: string,
339	  newName: string
340	): AIProcessedItem[] {
341	  const oldTrim = (oldName || '').trim();
342	  const newTrim = (newName || '').trim();
343	  if (!newTrim || oldTrim === newTrim) return items;
344	
345	  return items.map(i => {
346	    const cat = (i.category?.trim() || 'Geral');
347	    const man = (i.manualCategory || '').trim();
348	    if (cat === oldTrim || man === oldTrim) {
349	      return { ...i, category: newTrim, manualCategory: newTrim };
350	    }
351	    return i;
352	  });
353	}
