355	/** Verifica se uma categoria pode ser removida (não pode ter itens). */
356	export function canRemoveCategory(
357	  items: AIProcessedItem[],
358	  categoryName: string
359	): boolean {
360	  const trimmed = (categoryName || '').trim();
361	  if (!trimmed) return false;
362	  return !items.some(i => {
363	    const cat = (i.category?.trim() || 'Geral');
364	    const man = (i.manualCategory || '').trim();
365	    return cat === trimmed || man === trimmed;
366	  });
367	}
