393	/** Formata elapsed time em MM:SS. */
394	export function formatElapsed(seconds: number): string {
395	  const s = Math.max(0, Number(seconds) || 0);
396	  const mm = String(Math.floor(s / 60)).padStart(2, '0');
397	  const ss = String(s % 60).padStart(2, '0');
398	  return `${mm}:${ss}`;
399	}
