401	/** Extrai timestamp de enfileiramento de uma requisição. */
402	export function getQueueTimestamp(
403	  req: Record<string, unknown> | null | undefined,
404	  formatter: (v?: string | null) => string = formatDateTimeBr
405	): string {
406	  if (!req) return '—';
407	  const v = (req.enqueued_at ?? req.enqueuedAt ?? req.created_at ?? req.createdAt ?? null) as string | null;
408	  return formatter(v) || '—';
409	}
