1	/**
2	 * @module stringUtils
3	 *
4	 * Funções de normalização e comparação de strings, usadas para
5	 * correspondência fuzzy de nomes de produtos/itens.
6	 */
7	
8	/**
9	 * Normaliza um nome para comparação case-insensitive e sem acentos.
10	 *
11	 * Remove diacríticos (NFD), caracteres especiais e espaços extras.
12	 *
13	 * @param s - String a ser normalizada.
14	 * @returns String em lowercase, sem acentos, apenas `[a-z0-9\s]`.
15	 *
16	 * @example
17	 * ```ts
18	 * normalizeName("Pão de Mel (100g)"); // "pao de mel 100g"
19	 * ```
20	 */
21	export const normalizeName = (s: string): string => {
22	  return s
23	    .toLowerCase()
24	    .normalize('NFD')
25	    .replace(/[\u0300-\u036f]/g, '')
26	    .replace(/[^a-z0-9\s]/g, '')
27	    .replace(/\s+/g, ' ')
28	    .trim();
29	};
30	
31	/**
32	 * Calcula a distância de Levenshtein (edição) entre duas strings.
33	 *
34	 * @param a - Primeira string.
35	 * @param b - Segunda string.
36	 * @returns Número mínimo de inserções, remoções ou substituições para transformar `a` em `b`.
37	 *
38	 * @example
39	 * ```ts
40	 * levenshtein("gato", "rato"); // 1
41	 * ```
42	 */
43	export const levenshtein = (a: string, b: string): number => {
44	  const m = a.length, n = b.length;
45	  if (m === 0) return n;
46	  if (n === 0) return m;
47	  const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
48	  for (let i = 0; i <= m; i++) dp[i][0] = i;
49	  for (let j = 0; j <= n; j++) dp[0][j] = j;
50	  for (let i = 1; i <= m; i++) {
51	    for (let j = 1; j <= n; j++) {
52	      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
53	      dp[i][j] = Math.min(
54	        dp[i - 1][j] + 1,
55	        dp[i][j - 1] + 1,
56	        dp[i - 1][j - 1] + cost,
57	      );
58	    }
59	  }
60	  return dp[m][n];
61	};
62	
63	/**
64	 * Retorna um score de similaridade entre 0 e 1 para duas strings.
65	 *
66	 * Utiliza Levenshtein normalizado sobre os nomes após {@link normalizeName},
67	 * com bônus de +0.1 quando uma string é substring da outra.
68	 *
69	 * @param a - Primeira string (original, não normalizada).
70	 * @param b - Segunda string (original, não normalizada).
71	 * @returns Score de 0 (completamente diferentes) a 1 (idênticos).
72	 *
73	 * @example
74	 * ```ts
75	 * similarity("Bolo de chocolate", "Bolo Chocolate"); // ~0.85
76	 * similarity("Pão", "Queijo");                       // ~0.0
77	 * ```
78	 */
79	export const similarity = (a: string, b: string): number => {
80	  const na = normalizeName(a);
81	  const nb = normalizeName(b);
82	  if (!na || !nb) return 0;
83	  const dist = levenshtein(na, nb);
84	  const maxLen = Math.max(na.length, nb.length);
85	  const baseScore = 1 - dist / maxLen;
86	  const substrBonus = (na.includes(nb) || nb.includes(na)) ? 0.1 : 0;
87	  return Math.max(0, Math.min(1, baseScore + substrBonus));
88	};
