1	/**
2	 * @module useProductAliases
3	 *
4	 * Hook para gestão de apelidos (aliases) de produtos. Permite
5	 * aprender novas variações de nome e buscar produtos por alias
6	 * normalizado, removendo acentos, plurais e caracteres especiais.
7	 */
8	
9	import { useState, useCallback, useEffect } from 'react';
10	import { supabase } from '@/integrations/supabase/client';
11	import { toast } from 'sonner';
12	import { handleError } from '@/shared/lib/error-handler';
13	import { wideDebug } from '@/shared/lib/telemetry/wide-events';
14	
15	/** Apelido (variação de nome) vinculado a um produto. */
16	export interface ProductAlias {
17	  id: number;
18	  produto_id: number;
19	  alias: string;
20	  used_count: number;
21	}
22	
23	/**
24	 * Normaliza texto para comparação de aliases: remove acentos,
25	 * caracteres especiais, plural simples e converte para minúsculas.
26	 *
27	 * @param text - Texto a ser normalizado.
28	 * @returns String normalizada para comparação.
29	 */
30	export function normalizeAlias(text: string): string {
31	  if (!text) return '';
32	
33	  return (
34	    text
35	      // Remove acentos e diacríticos
36	      .normalize('NFD')
37	      .replace(/[\u0300-\u036f]/g, '')
38	      // Remove caracteres especiais (mantém letras, números e espaços)
39	      .replace(/[^a-zA-Z0-9\s]/g, '')
40	      // Converte para minúsculas
41	      .toLowerCase()
42	      // Remove 's' final de palavras (plural simples) - CUIDADO: pode afetar palavras terminadas em s como "oásis"
43	      // Mas para fins de alias, "copo" e "copos" devem ser o mesmo.
44	      .replace(/s\b/g, '')
45	      // Remove espaços extras
46	      .replace(/\s+/g, ' ')
47	      .trim()
48	  );
49	}
50	
51	/**
52	 * Gerencia apelidos de produtos com aprendizado automático.
53	 *
54	 * Carrega aliases da tabela `produto_aliases`, permite adicionar
55	 * novos aliases normalizados e buscar produto por texto via
56	 * `findProductByAlias`.
57	 *
58	 * @returns Aliases, estado de loading e funções de CRUD/busca.
59	 */
60	export function useProductAliases() {
61	  const [aliases, setAliases] = useState<ProductAlias[]>([]);
62	  const [loading, setLoading] = useState(false);
63	
64	  // Carregar todos os aliases ao iniciar (pode ser otimizado depois se crescer muito)
65	  const fetchAliases = useCallback(async () => {
66	    setLoading(true);
67	    try {
68	      const { data, error } = await (supabase as any)
69	        .from('produto_aliases')
70	        .select('*, produtos_master!inner(ativo)')
71	        .eq('produtos_master.ativo', true);
72	
73	      if (error) {
74	        handleError(error, { domain: 'produtos', operation: 'fetchAliases', showToast: false });
75	        return;
76	      }
77	
78	      setAliases(data || []);
79	    } catch (error) {
80	      handleError(error, { domain: 'produtos', operation: 'fetchAliases', showToast: false });
81	    } finally {
82	      setLoading(false);
83	    }
84	  }, []);
85	
86	  // Adicionar novo alias
87	  const addAlias = useCallback(
88	    async (produtoId: number, aliasText: string, silent = false) => {
89	      if (!aliasText || !produtoId) return null;
90	
91	      // Normalização agressiva antes de salvar
92	      const normalizedAlias = normalizeAlias(aliasText);
93	
94	      // Se após normalização ficar vazio (ex: só tinha caracteres especiais), aborta
95	      if (!normalizedAlias || normalizedAlias.length < 2) return null;
96	
97	      // Verificar se já existe localmente para evitar chamada desnecessária
98	      const exists = aliases.some(
99	        (a) => normalizeAlias(a.alias) === normalizedAlias,
100	      );
101	      if (exists) {
102	        wideDebug('produtos.alias_already_known', 'Alias já conhecido (match normalizado)', { domain: 'produtos', attributes: { alias: normalizedAlias } });
103	        return null;
104	      }
105	
106	      try {
107	        const { data, error } = await (supabase as any)
108	          .from('produto_aliases')
109	          .insert({
110	            produto_id: produtoId,
111	            alias: normalizedAlias,
112	          })
113	          .select()
114	          .single();
115	
116	        if (error) {
117	          // Se for erro de duplicidade (código 23505), apenas ignoramos
118	          if (error.code === '23505') {
119	            wideDebug('produtos.alias_duplicate', 'Alias já existe no banco', { domain: 'produtos', attributes: { alias: normalizedAlias } });
120	            return null;
121	          }
122	          handleError(error, { domain: 'produtos', operation: 'addAlias', showToast: false });
123	          toast.error('Erro ao salvar variação do produto');
124	          return null;
125	        }
126	
127	        // Atualizar estado local
128	        setAliases((prev) => [...prev, data]);
129	        if (!silent) toast.success('Nova variação aprendida pelo sistema!');
130	        return data;
131	      } catch (error) {
132	        handleError(error, { domain: 'produtos', operation: 'addAlias', showToast: false });
133	        return null;
134	      }
135	    },
136	    [aliases],
137	  );
138	
139	  // Buscar produto por alias (retorna ID do produto ou null)
140	  const findProductByAlias = useCallback(
141	    (text: string): number | null => {
142	      if (!text) return null;
143	
144	      const normalizedInput = normalizeAlias(text);
145	      if (!normalizedInput) return null;
146	
147	      // Busca com normalização em ambos os lados
148	      const found = aliases.find(
149	        (a) => normalizeAlias(a.alias) === normalizedInput,
150	      );
151	
152	      if (found) {
153	        wideDebug('produtos.alias_match', `Alias encontrado: "${text}" -> "${normalizedInput}"`, { domain: 'produtos', attributes: { text, normalizedInput, produtoId: found.produto_id } });
154	      }
155	
156	      return found ? found.produto_id : null;
157	    },
158	    [aliases],
159	  );
160	
161	  // Carregar aliases na montagem
162	  useEffect(() => {
163	    fetchAliases();
164	  }, [fetchAliases]);
165	
166	  return {
167	    aliases,
168	    loading,
169	    fetchAliases,
170	    addAlias,
171	    findProductByAlias,
172	  };
173	}
