```

**Adding New Alias (Lines 87–137):**
```typescript
const addAlias = useCallback(
  async (produtoId: number, aliasText: string, silent = false) => {
    if (!aliasText || !produtoId) return null;

    const normalizedAlias = normalizeAlias(aliasText);

    if (!normalizedAlias || normalizedAlias.length < 2) return null;

    // Local dedup check
    const exists = aliases.some(
      (a) => normalizeAlias(a.alias) === normalizedAlias,
    );
    if (exists) return null;

    try {
      const { data, error } = await (supabase as any)
        .from('produto_aliases')
        .insert({
          produto_id: produtoId,
          alias: normalizedAlias,
        })
        .select()
        .single();

      if (error) {
        if (error.code === '23505') {  // Duplicate key error
          return null;
        }
        // ... error handling
      }

      setAliases((prev) => [...prev, data]);
      if (!silent) toast.success('Nova variação aprendida pelo sistema!');
      return data;
    }
  },
  [aliases],
);
```

**Finding by Alias (Lines 140–159):**
```typescript
const findProductByAlias = useCallback(
  (text: string): number | null => {
    if (!text) return null;

    const normalizedInput = normalizeAlias(text);
    if (!normalizedInput) return null;

    const found = aliases.find(
      (a) => normalizeAlias(a.alias) === normalizedInput,
    );

    if (found) {
      wideDebug('produtos.alias_match', `Alias encontrado: "${text}" -> "${normalizedInput}"`,
        { domain: 'produtos', attributes: { text, normalizedInput, produtoId: found.produto_id } });
    }

    return found ? found.produto_id : null;
  },
  [aliases],
);
```

#### **How Aliases Are Learned (Requisition Page, Lines 825–852)**

```typescript
const handleChangeMatch = async (index: number, product: { id: number; nome: string; ... }) => {
  const originalItem = allItems[index];
  if (originalItem) {
    const productNormalized = normalizeAlias(product.nome.trim());
    const vistos = new Set<string>();
    const termos = [originalItem.sourceText, originalItem.originalName]
      .map((t) => (t || "").trim())
      .filter((t) => {
        const n = normalizeAlias(t);
        if (n.length < 3 || n === productNormalized || vistos.has(n)) return false;
        vistos.add(n);
        return true;
      });
    if (termos.length > 0) {
      // fire-and-forget
      Promise.all(termos.map((t) => addAlias(product.id, t, true))).then((results) => {
        if (results.some(Boolean)) {
          toast.success(`Sistema aprendeu que "${termos[0]}" é "${product.nome.trim()}"!`);
          fetchAliases();
        }
      });
    }
  }
  // ... then update the item
};
```

**Alias Priority in Matching (Requisicao.page.tsx, Lines 2572–2583):**
```typescript
